            var mark = document.createElement('div')
            mark.className = 'dsh-wk-pdfhl'
            mark.style.left = tx[4] + 'px'
            mark.style.top = (tx[5] - hgt) + 'px'
            mark.style.width = w + 'px'
            mark.style.height = hgt + 'px'
            wrap.appendChild(mark)
